static uint64_t bynh_hash_str(byn_str k) {
    return byn_hash_bytes(k.ptr, k.len);
}

static bool bynh_keq_str(const void* a, const void* b) {
    return byn_str_eq(*(const byn_str*)a, *(const byn_str*)b);
}

static bool bynh_has_map_str_i64(bynt_map_str_i64 m, byn_str k) {
    return byn_map_find(&m.h, m.keys, (int64_t)sizeof(byn_str), &k, bynh_hash_str(k), bynh_keq_str) >= 0;
}

static int64_t bynh_index_map_str_i64(bynt_map_str_i64 m, byn_str k, const char* file, int line) {
    int64_t i = byn_map_find(&m.h, m.keys, (int64_t)sizeof(byn_str), &k, bynh_hash_str(k), bynh_keq_str);
    if (i < 0) byn_panic("key not found in map", file, line);
    return m.vals[i];
}

